const long long ZERO = 0LL;
const long long INF64 = 1e18;
const int INF32 = 1e9;
const int MOD = 1e9 + 7;
const double PI = acos(-1.0L);
const double EPS = static_cast<double>(1e-9);
typedef long long ll;

int modVal(int a) {
  return ((a % MOD) + MOD) % MOD;
}

int prod(int a, int b) {
  return int(a * 1LL * b % MOD);
}

int fastExponent(int a, int k) {
  int res = 1;
  while (k > 0) {
    if (k & 1) res = prod(res, a);
    a = prod(a, a);
    k >>= 1;
  }
  return res;
}

int getInverse(int a) {
  int b = fastExponent(a, MOD - 2);
  assert(prod(a, b) == 1);
  return b;
}

struct Edge {
  int y;
  int capacity;
  int flow;
  int cost;

  Edge() {};

  Edge(int _y, int _capacity, int _flow, int _cost) 
    : y(_y), capacity(_capacity), flow(_flow), cost(_cost) {};
};

vector<Edge> edgeList;

const int MAXNODES = 1e6 + 7;
vector<int> adjList[MAXNODES];

ll totalCostSum = 0;
ll distArray[MAXNODES];
int predArray[MAXNODES];
int peArray[MAXNODES];
int inQ[MAXNODES];

int sNode = MAXNODES - 2;
int tNode = MAXNODES - 1;

int residualCap(int x) {
  return edgeList[x].capacity - edgeList[x].flow;
}

void findFlow() {
  for (int i = 0; i < MAXNODES; i++) {
    distArray[i] = INF64;
    predArray[i] = -1;
    peArray[i] = -1;
    inQ[i] = 0;
  }
  distArray[sNode] = 0;
  std::queue<int> q;
  q.push(sNode);
  inQ[sNode] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQ[u] = 0;
    for (auto eIdx : adjList[u]) {
      if (!residualCap(eIdx)) continue;
      int cst = edgeList[eIdx].cost;
      int y = edgeList[eIdx].y;
      if (distArray[y] > distArray[u] + cst) {
        distArray[y] = distArray[u] + cst;
        predArray[y] = u;
        peArray[y] = eIdx;
        if (inQ[y] == 0) {
          inQ[y] = 1;
          q.push(y);
        }
      }
    }
  }
  int cur = tNode;
  while (cur != sNode) {
    edgeList[peArray[cur]].flow++;
    edgeList[peArray[cur] ^ 1].flow--;
    cur = predArray[cur];
  }
  totalCostSum += distArray[tNode];
}

void addEdgeToGraph(int x, int y, int cap, int cst) {
  adjList[x].push_back(edgeList.size());
  edgeList.emplace_back(y, cap, 0, cst);
  adjList[y].push_back(edgeList.size());
  edgeList.emplace_back(x, 0, 0, -cst);
}

