  for (int i = 0; i < n; i++) {
    for (int j = 0; j < layersCount - 1; j++) {
      addEdgeToGraph(i + j * n, i + j * n + n, k, 0);
    }
  }
  for (int i = 0; i < k; i++) {
    findFlow();
  }
  printf("%lld\n", totalCostSum);
}

